#!/usr/bin/env node
/**
 * dream-llm-annotate.mjs — optional local-LLM "why these connect" prose pass for
 * the Hermes dream-cycle (`scripts/hermes-dream-cycle-synth.mjs`, U-GALAXY-MS1-B1).
 *
 * The dream-cycle surfaces cross-memo connections by keyword-set Jaccard and
 * writes bare `[[A]] ↔ [[B]] — shared: kw1,kw2` edges into
 * knowledge/memories/dreams/<date>.md for Obsidian's graph view. The Jaccard tells
 * you THAT two notes share vocabulary; it never says WHY they connect. This adds
 * a one-sentence latent-insight rationale per top edge, generated by the local
 * Blackwell model (qwen2.5-coder:32b) — $0 Claude tokens. Default-OFF
 * (PRISM_DREAM_LLM_SYNTH=1) and fail-open: model down / timeout / "NONE" → the
 * bare edge (exactly the prior output). On-goal: enriches vault context with
 * EXPLAINED connections (context expansion), not just denser edges.
 *
 * Pure exports: buildConnectionPrompt, cleanRationale. Async: annotateConnections.
 */

// Annotate at most this many top connections (by Jaccard) per run — bounds the
// per-run LLM cost on the dream cron. Knob: PRISM_DREAM_LLM_TOP_N.
export const DREAM_LLM_TOP_N = Number(process.env.PRISM_DREAM_LLM_TOP_N) || 15;
// A rationale longer than this many words is unfocused (the model rambled) →
// dropped rather than bloating the vault edge. Knob: PRISM_DREAM_LLM_MAX_WORDS.
export const DREAM_LLM_MAX_WORDS = Number(process.env.PRISM_DREAM_LLM_MAX_WORDS) || 30;

// memo filename → readable phrase: drop .md, the type prefix, and a trailing
// _YYYY_MM_DD date stamp, then de-kebab. "reference_xray_ocr_gpu_concurrency_2026_05_31.md"
// → "xray ocr gpu concurrency". Pure.
export function readableName(name) {
  return String(name || "")
    .replace(/\.md$/i, "")
    .replace(/^(feedback|reference|project|user)_/i, "")
    .replace(/_\d{4}[_-]\d{2}[_-]\d{2}$/, "")
    .replace(/[_-]+/g, " ")
    .trim();
}

/**
 * Pure: build the one-sentence-rationale prompt for a connection. `c` has the
 * dream-cycle connection shape { a:{name}, b:{name}, shared:[kw...] }.
 */
export function buildConnectionPrompt(c) {
  const a = readableName(c?.a?.name);
  const b = readableName(c?.b?.name);
  const shared = (Array.isArray(c?.shared) ? c.shared : []).slice(0, 8).join(", ");
  return [
    "Two PRISM engineering notes were linked because they share concepts.",
    `Note A: "${a}".`,
    `Note B: "${b}".`,
    `Shared concepts: ${shared}.`,
    "In ONE concise sentence (max 25 words), state the most likely SUBSTANTIVE reason",
    "these two notes connect — the latent engineering insight, NOT a restatement of",
    "the shared words. If there is no meaningful connection, reply exactly: NONE",
  ].join(" ");
}

/**
 * Pure: normalise a model reply into a vault-safe one-line rationale, or "" to
 * drop it. Drops empty / NONE / over-long (rambling) / and strips wrapping
 * quotes + a leading "Because"/"The connection is" filler.
 */
export function cleanRationale(text, maxWords = DREAM_LLM_MAX_WORDS) {
  if (typeof text !== "string") return "";
  let r = text.trim();
  if (!r) return "";
  r = r.split(/\r?\n/)[0].trim();              // first line only
  r = r.replace(/^["'`]+|["'`]+$/g, "").trim(); // strip wrapping quotes
  if (/^none\b/i.test(r) || r.toUpperCase() === "NONE") return "";
  if (r.split(/\s+/).length > maxWords) return ""; // rambled → drop
  return r;
}

/**
 * Annotate the top-N connections (by Jaccard) with an LLM rationale, in place.
 * `callFn(prompt) => Promise<string|null>` is injected (live: callOllama bound to
 * the resolved synthesis model; tests: a stub). Fail-open per edge — any
 * error/empty leaves that edge bare. Returns the same connections array.
 */
export async function annotateConnections(connections, opts = {}) {
  const callFn = opts.callFn;
  const topN = Number.isFinite(opts.topN) ? opts.topN : DREAM_LLM_TOP_N;
  const maxWords = Number.isFinite(opts.maxWords) ? opts.maxWords : DREAM_LLM_MAX_WORDS;
  if (typeof callFn !== "function" || !Array.isArray(connections) || connections.length === 0) {
    return connections;
  }
  // Same objects as the originals (sort a shallow copy) → attaching .rationale
  // here annotates the connections the renderer will emit.
  const ranked = [...connections].sort((x, y) => (y.jaccard ?? 0) - (x.jaccard ?? 0)).slice(0, Math.max(0, topN));
  for (const c of ranked) {
    try {
      const out = await callFn(buildConnectionPrompt(c));
      const r = cleanRationale(out, maxWords);
      if (r) c.rationale = r;
    } catch { /* fail-open: leave this edge bare */ }
  }
  return connections;
}
